// Control Rig units of the animation plugin (presentation only).

#include "GSTN_RigUnit_PreviewLimbSurface.h"

#include "Engine/World.h"
#include "GSTN_LimbContactUtils.h"
#include "Rigs/RigHierarchy.h"
#include "Units/RigUnitContext.h"

#include UE_INLINE_GENERATED_CPP_BY_NAME(GSTN_RigUnit_PreviewLimbSurface)

// Body of Execute(): the macro is generated by UHT for RIGVM_METHOD, as in the engine units
FGSTN_RigUnit_PreviewLimbSurface_Execute()
{
	ResultSurface = Surface;
	ResultWeight = Weight;
	bPreviewActive = false;

	const URigHierarchy* Hierarchy = ExecuteContext.Hierarchy;
	if (!bEnabled || !Hierarchy)
	{
		return;
	}

	if (bOnlyInEditorPreview)
	{
		const UWorld* World = ExecuteContext.GetWorld();
		if (!World || World->WorldType != EWorldType::EditorPreview)
		{
			return;
		}
	}

	if (!CachedWall.UpdateCache(Wall, Hierarchy))
	{
		return;
	}

	ResultSurface = UGSTN_LimbContactUtils::SurfaceFromTransform(Hierarchy->GetGlobalTransform(CachedWall.GetIndex()));
	ResultWeight = 1.f;
	bPreviewActive = true;
}
